export function buildSystemPrompt({ restrained }) {
  return joinPromptLines([
    sysPrompt(restrained),
    "\u041d\u0435 \u0443\u043f\u043e\u043c\u0438\u043d\u0430\u0439 \u0443\u0434\u0430\u043b\u0451\u043d\u043d\u044b\u0435 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u044b, \u0441\u0442\u0430\u0440\u044b\u0435 \u0430\u0440\u0445\u0438\u0432\u044b \u0438 \u043d\u0435\u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0443\u044e\u0449\u0438\u0435 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0438."
  ]);
}

