export function looksLikeGroupQuestion(text, normalize = (value) => String(value || "").toLowerCase().replace(/\u0451/g, "\u0435")) {
  const normalized = normalize(text);
  const hasAny = (phrases) => phrases.some((phrase) => normalized.includes(phrase));
  const hasTopic = hasAny(GROUP_TOPIC_PHRASES);
  const hasQuestionCue = hasAny(GROUP_QUESTION_PHRASES);
  const hasGroupCue = hasAny(GROUP_SCOPE_PHRASES);
  return hasTopic || (hasQuestionCue && hasGroupCue);
}

