export function scoreChunkBonus(source, q) {
  const question = String(q || "").toLowerCase().replace(/\u0451/g, "\u0435");
  if (source === "FAQ" && FAQ_SCORE_RE.test(question)) return 10;
  if (source === "График служений" && SCHEDULE_SCORE_RE.test(question)) return 8;
  if (source === "Список служащих/ротация" && ROTATION_SCORE_RE.test(question)) return 10;
  return 0;
}
